#if UNITY_EDITOR
using UnityEditor;
using UnityEditor.Build.Profile.Components;
using UnityEngine;

public static class BuildScript
{
    public static void Build()
    {
        BuildPlayerOptions o = new BuildPlayerOptions();
        o.scenes = new[] { "Assets/Scenes/Main.unity" };
        o.locationPathName = "Builds/PC/Game.exe";
        o.target = BuildTarget.StandaloneWindows64;
        o.options = BuildOptions.None;
        BuildPipeline.BuildPlayer(o);
    }
}
#endif
